/* Generated by scripts/build.js from scripts/guide.js. Do not edit by hand. */
window.RainlineHelperData = {"crops":{"peas":{"difficulty":1,"sun":"Full sun; tolerates light shade","spacing":"2 inches apart along a trellis","depth":"1 inch deep","harvest":"Pick snap and snow peas when pods are plump but still crisp, every two or three days.","problem":"Birds and slugs go after young shoots. Cover rows with netting until plants are a few inches tall.","varieties":["Oregon Sugar Pod II","Sugar Snap","Green Arrow"]},"radishes":{"difficulty":1,"sun":"Full sun; tolerates light shade","spacing":"1 inch apart (thin to 2 inches)","depth":"½ inch deep","harvest":"Most are ready in about four weeks. Pull them while they're small; they turn woody if left too long.","problem":"Cabbage root maggots tunnel into roots in cool, wet springs. Row cover laid on at sowing keeps the flies off.","varieties":["Cherry Belle","French Breakfast","Easter Egg"]},"spinach":{"difficulty":2,"sun":"Full sun to part shade","spacing":"3 inches apart","depth":"½ inch deep","harvest":"Cut outer leaves once plants have five or six, or cut the whole plant before it sends up a flower stalk.","problem":"Bolts (goes to seed) as days lengthen in late spring. Sow early, and sow again in late summer for fall and winter.","varieties":["Bloomsdale Long Standing","Space","Giant Winter (for fall sowing)"]},"lettuce":{"difficulty":1,"sun":"Full sun in spring; afternoon shade in summer","spacing":"8 to 10 inches apart for heads","depth":"¼ inch deep (it needs light to sprout)","harvest":"Pick outer leaves as needed, or cut whole heads when full. Harvest in the morning for the crispest leaves.","problem":"Slugs are the Northwest lettuce pest. Iron phosphate slug bait is safe around pets and edible crops.","varieties":["Buttercrunch","Black Seeded Simpson","Winter Density"]},"onions":{"difficulty":2,"sun":"Full sun","spacing":"4 inches apart","depth":"Sets 1 inch deep, tip just showing","harvest":"When the tops flop over in late summer, pull the onions and let them dry in a shady, airy spot for two weeks.","problem":"Weeds outcompete onions' thin leaves. Keep the bed weeded and mulched.","varieties":["Walla Walla Sweet","Copra (stores well)","Redwing"]},"carrots":{"difficulty":2,"sun":"Full sun","spacing":"Thin to 2 inches apart","depth":"¼ inch deep","harvest":"Pull when the shoulders are about ¾ inch across. Fall carrots sweeten after a light frost.","problem":"Carrot rust fly larvae tunnel through roots. Cover the bed with insect netting from sowing on.","varieties":["Scarlet Nantes","Bolero","Danvers"]},"beets":{"difficulty":2,"sun":"Full sun; tolerates light shade","spacing":"Thin to 3 inches apart","depth":"½ inch deep","harvest":"Pull at golf ball to tennis ball size. The greens are edible too.","problem":"Leaf miners leave pale trails in the leaves. Pick off affected leaves and use row cover.","varieties":["Detroit Dark Red","Chioggia","Early Wonder"]},"kale":{"difficulty":1,"sun":"Full sun to part shade","spacing":"18 inches apart","depth":"Plant starts at the depth they grew in the pot","harvest":"Pick the lower leaves and let the top keep growing. Plants often produce from fall through spring west of the Cascades.","problem":"Cabbage worms and aphids. Row cover keeps the white cabbage moths from laying eggs.","varieties":["Lacinato","Red Russian","Winterbor"]},"broccoli":{"difficulty":2,"sun":"Full sun","spacing":"18 inches apart","depth":"Plant starts at the depth they grew in the pot","harvest":"Cut the main head while the buds are tight and dark green. Side shoots follow for weeks.","problem":"Cabbage worms and aphids. Cover young plants with insect netting.","varieties":["Packman","Green Magic","Purple Sprouting (overwinters west of the Cascades)"]},"cabbage":{"difficulty":2,"sun":"Full sun","spacing":"18 inches apart","depth":"Plant starts at the depth they grew in the pot","harvest":"Cut when heads feel firm when squeezed. Water evenly to keep heads from splitting.","problem":"Cabbage worms and root maggots. Row cover from planting day prevents both.","varieties":["Golden Acre","Early Jersey Wakefield","January King (winter)"]},"chard":{"difficulty":1,"sun":"Full sun to part shade","spacing":"10 inches apart","depth":"½ inch deep","harvest":"Cut outer stalks at the base. One planting keeps producing from early summer into winter.","problem":"Leaf miners, the same as beets. Remove spotted leaves early.","varieties":["Bright Lights","Fordhook Giant","Rhubarb"]},"potatoes":{"difficulty":1,"sun":"Full sun","spacing":"12 inches apart in rows 30 inches apart","depth":"4 inches deep in a trench","harvest":"Dig new potatoes when the plants flower. For storage potatoes, wait two weeks after the tops die back.","problem":"Wireworms in beds that were recently lawn. Grow potatoes in an established bed if you can.","varieties":["Yukon Gold","German Butterball","Red Norland"]},"beans":{"difficulty":1,"sun":"Full sun","spacing":"3 inches apart","depth":"1 inch deep","harvest":"Pick when pods are pencil-thick and before the seeds bulge. Picking often keeps plants producing.","problem":"Seeds rot in cold, wet soil, the most common Northwest bean failure. Wait for warm soil.","varieties":["Provider (sprouts in cooler soil)","Blue Lake 274","Royal Burgundy"]},"corn":{"difficulty":2,"sun":"Full sun","spacing":"10 inches apart in a block of short rows","depth":"1 inch deep","harvest":"Ready about three weeks after the silks appear, when the silks are brown and the kernels squirt milky juice.","problem":"Crows pull up sprouting seeds. Cover the bed with netting or row cover until plants are 4 inches tall.","varieties":["Early Sunglow","Bodacious","Golden Bantam"]},"cucumbers":{"difficulty":2,"sun":"Full sun","spacing":"12 inches apart on a trellis","depth":"1 inch deep","harvest":"Pick slicers at 6 to 8 inches, before they yellow. Check plants every day or two in midsummer.","problem":"Powdery mildew in late summer. Grow them up a trellis for airflow and water at the base.","varieties":["Marketmore 76","Lemon","Diva"]},"summer-squash":{"difficulty":1,"sun":"Full sun","spacing":"3 feet apart","depth":"1 inch deep","harvest":"Pick zucchini at 6 to 8 inches. Miss a few days and you'll have a baseball bat.","problem":"Powdery mildew late in the season. Remove the worst leaves and keep watering at the base.","varieties":["Black Beauty","Costata Romanesco","Early Prolific Straightneck"]},"winter-squash":{"difficulty":2,"sun":"Full sun","spacing":"4 feet apart (vines spread)","depth":"1 inch deep","harvest":"Cut when the rind resists a fingernail and the stem is dry, before a hard frost. Cure in a warm room for two weeks.","problem":"A short or cool season. Delicata and other fast varieties ripen far more reliably here than big pumpkins.","varieties":["Delicata","Sugar Pie pumpkin","Sweet Meat (an Oregon heirloom)"]},"tomatoes":{"difficulty":2,"sun":"Full sun; the hottest spot you have","spacing":"2 feet apart","depth":"Bury the stem up to the first leaves","harvest":"Pick when fully colored. Before fall rains, pick green tomatoes and ripen them indoors.","problem":"Late blight in wet falls turns leaves and fruit brown. Keep leaves dry and give plants space.","varieties":["Stupice","Early Girl","Sungold (cherry)","Oregon Spring (bred in Oregon)"]},"peppers":{"difficulty":3,"sun":"Full sun; against a warm wall if possible","spacing":"18 inches apart","depth":"Plant starts at the depth they grew in the pot","harvest":"Pick green any time once full size, or leave them to ripen red, which can take three more weeks.","problem":"Cool nights stall growth. Black plastic mulch and row cover early in the season make a big difference here.","varieties":["Gypsy","Ace","Early Jalapeño","Lunchbox snacking peppers"]},"basil":{"difficulty":2,"sun":"Full sun","spacing":"12 inches apart","depth":"Plant starts at the depth they grew in the pot","harvest":"Pinch off the top pair of leaves often so plants bush out, and remove flower buds.","problem":"Cold. Basil blackens below about 40°F, so it goes out last and comes in at the first chilly night.","varieties":["Genovese","Thai","Spicy Globe"]},"dahlias":{"difficulty":2,"sun":"Full sun","spacing":"18 to 24 inches apart","depth":"4 to 6 inches deep, eye pointing up","plantText":"dahlia tubers","firstHarvest":"Blooms from midsummer until the first frost","harvest":"Cut flowers when they're almost fully open, early in the morning. The more you cut, the more they bloom.","problem":"Slugs and earwigs chew young shoots and petals. Use iron phosphate slug bait early in the season.","varieties":["Café au Lait","Bishop of Llandaff","Cornel Brons"],"care":"Don't water tubers until shoots appear, then water deeply once a week. Stake tall varieties when you plant so you don't spear the tuber later."},"cilantro":{"difficulty":1,"sun":"Full sun; afternoon shade in summer","spacing":"4 inches apart","depth":"¼ inch deep","harvest":"Cut leaves once plants are about 6 inches tall. If it bolts, let it go to seed and harvest the coriander.","problem":"Bolting in warm weather. Look for slow-bolt varieties and sow little and often.","varieties":["Calypso (slow to bolt)","Santo","Leisure"]},"parsley":{"difficulty":1,"sun":"Full sun to part shade","spacing":"8 inches apart","depth":"¼ inch deep","harvest":"Cut outer stems at the base and let the center keep growing.","problem":"Slow, patchy sprouting. Soak seeds overnight before sowing, or buy young plants.","varieties":["Italian Flat Leaf","Moss Curled","Giant of Italy"]},"dill":{"difficulty":1,"sun":"Full sun","spacing":"12 inches apart","depth":"¼ inch deep","harvest":"Snip leaves any time. For pickling, cut the flower heads just as they open.","problem":"Tall plants flop in wind and rain. Grow 'Fernleaf', a compact variety, or give it a stake.","varieties":["Fernleaf (compact)","Bouquet","Mammoth"]},"strawberries":{"difficulty":1,"sun":"Full sun","spacing":"12 to 18 inches apart","depth":"Crown at soil level: not buried, roots covered","plantText":"strawberry plants","firstHarvest":"A light crop the first summer; full crops from the second year","harvest":"Pick fully red berries every couple of days, in the morning, with the cap attached.","problem":"Gray mold (botrytis) in wet springs and slugs on ripe berries. Mulch with straw to keep fruit off the soil.","varieties":["Hood (an Oregon classic)","Shuksan","Seascape (everbearing)","Albion (day-neutral)"],"care":"Water regularly, mulch with straw, and pinch off runners in the first year so plants put energy into roots."},"blueberries":{"difficulty":1,"sun":"Full sun","spacing":"4 to 5 feet apart","depth":"Same depth as in the pot","plantText":"blueberry bushes","firstHarvest":"Small crops in year two or three; full crops by year five","harvest":"Pick berries a few days after they turn fully blue, when they roll off into your hand.","problem":"Birds. Cover bushes with netting as berries color, or plant extra.","varieties":["Duke (early)","Chandler (huge berries)","Bluecrop","Top Hat (for containers)"],"care":"Mix peat moss or acidic compost into the planting hole, mulch with sawdust or bark, and pinch off flowers the first year."},"raspberries":{"difficulty":2,"sun":"Full sun","spacing":"2 to 3 feet apart in rows","depth":"Roots covered by 2 to 3 inches of soil","plantText":"raspberry canes","firstHarvest":"Light crop in year two (fall-bearers can fruit the first fall)","harvest":"Pick when berries slip easily off the core. Check every two or three days in season.","problem":"Root rot in soggy soil. Plant in a raised row or a bed that drains well.","varieties":["Meeker (a Northwest favorite)","Tulameen","Heritage (fall-bearing)","Cascade Delight"],"care":"Set up a simple trellis with posts and wire. After harvest, cut spent canes to the ground."},"garlic":{"difficulty":1,"sun":"Full sun","spacing":"6 inches apart","depth":"2 inches deep, pointed end up","harvest":"Dig in early summer when the lower third of the leaves are brown. Cure in a shady, airy spot for three weeks.","problem":"Rust (orange spots on leaves) in wet springs. It's mostly cosmetic; give plants space and pull weeds.","varieties":["Music (hardneck)","Inchelium Red (softneck, from Washington)","Chesnok Red"]},"cauliflower":{"difficulty":3,"sun":"Full sun","spacing":"18 to 24 inches apart","depth":"Plant starts at the depth they grew in the pot","harvest":"Cut the head while it's firm and tight, before the curds start to separate. Tie the outer leaves over young heads to keep them white.","problem":"A cold snap or dry spell makes plants form tiny 'button' heads. Keep the soil evenly moist and don't rush spring planting.","varieties":["Snow Crown","Amazing","Graffiti (purple)"]},"brussels-sprouts":{"difficulty":2,"sun":"Full sun","spacing":"24 inches apart","depth":"Plant starts at the depth they grew in the pot","harvest":"Pick sprouts from the bottom of the stalk up once they're firm and about an inch across. Frost improves the flavor.","problem":"Aphids cluster on the sprouts in late summer. Knock them off with a strong spray of water every few days.","varieties":["Long Island Improved","Diablo","Churchill"]},"leeks":{"difficulty":1,"sun":"Full sun","spacing":"6 inches apart","depth":"Set seedlings in a hole about 6 inches deep so the stems grow long and white","harvest":"Dig whenever stems are an inch or more across. West of the Cascades you can leave them in the ground and harvest all winter.","problem":"Weeds crowd young leeks. Mulch and weed regularly while the plants are small.","varieties":["King Richard (early)","Bandit (winter-hardy)","American Flag"]},"arugula":{"difficulty":1,"sun":"Full sun to part shade","spacing":"Thin to 4 inches apart","depth":"¼ inch deep","harvest":"Pick leaves when they're 2 to 3 inches long, about three weeks after sowing. Young leaves are the mildest.","problem":"Flea beetles riddle the leaves with tiny holes in spring. Floating row cover laid on at sowing keeps them off.","varieties":["Astro","Wild arugula (Sylvetta)","Rocket"]},"bok-choy":{"difficulty":1,"sun":"Full sun to part shade","spacing":"6 to 10 inches apart","depth":"¼ inch deep","harvest":"Cut baby bok choy at about 6 inches tall, or whole heads at full size. Harvest before a flower stalk appears.","problem":"Flea beetles and slugs chew the leaves. Row cover and iron phosphate slug bait handle both.","varieties":["Joi Choi","Toy Choy (baby size)","Mei Qing Choi"]},"turnips":{"difficulty":1,"sun":"Full sun","spacing":"Thin to 4 inches apart","depth":"½ inch deep","harvest":"Pull at 2 to 3 inches across for tender roots. The greens are good to eat too.","problem":"Cabbage root maggots tunnel into roots in cool, wet soil. Cover the bed with row cover from sowing on.","varieties":["Hakurei (salad turnip)","Purple Top White Globe","Scarlet Queen"]},"kohlrabi":{"difficulty":1,"sun":"Full sun","spacing":"Thin to 6 inches apart","depth":"¼ to ½ inch deep","harvest":"Cut bulbs at 2 to 3 inches across. Peel off the tough skin and eat raw or cooked.","problem":"Cabbage worms chew the leaves. Insect netting keeps the white moths from laying eggs.","varieties":["Kolibri (purple)","Winner","Kossak (large, stores well)"]},"eggplant":{"difficulty":3,"sun":"Full sun; the hottest spot you have","spacing":"18 to 24 inches apart","depth":"Plant starts at the depth they grew in the pot","harvest":"Pick when the skin is glossy and springs back when pressed. Dull skin means it's overripe and seedy.","problem":"Flea beetles riddle young leaves, and cool nights stall growth. Keep row cover on until plants are growing strongly.","varieties":["Hansel (early, small fruit)","Fairy Tale","Orient Express"]},"melons":{"difficulty":3,"sun":"Full sun; the hottest spot you have","spacing":"24 to 36 inches apart","depth":"1 inch deep","harvest":"Cantaloupes are ripe when the stem slips off with a gentle push. Watermelons are ready when the curly tendril nearest the fruit turns brown and dry.","problem":"Cool soil and cool nights are the main obstacle west of the Cascades. Black plastic mulch and row cover until flowering make the difference.","varieties":["Sugar Baby (watermelon)","Minnesota Midget (cantaloupe)","Halona (cantaloupe)"]},"pole-beans":{"difficulty":1,"sun":"Full sun","spacing":"4 to 6 inches apart along a trellis","depth":"1 inch deep","harvest":"Pick when pods are pencil-thick and before the seeds bulge. Picking every few days keeps the vines producing.","problem":"Seeds rot in cold, wet soil, the most common Northwest bean failure. Wait for warm soil.","varieties":["Blue Lake FM-1K","Kentucky Wonder","Fortex"]},"fava-beans":{"difficulty":1,"sun":"Full sun","spacing":"6 inches apart","depth":"1 to 2 inches deep","harvest":"Pick pods when they bulge with beans but are still green. Shell the beans and slip off the pale skins for the sweetest flavor.","problem":"Black aphids gather on the growing tips in late spring. Pinch off the tips once pods start forming.","varieties":["Broad Windsor","Aquadulce Claudia (for fall sowing)","Vroma"]},"shallots":{"difficulty":1,"sun":"Full sun","spacing":"6 to 8 inches apart","depth":"Tip just at the soil surface","harvest":"Dig in summer when the tops yellow and fall over. Dry the clusters in a shady, airy spot for two weeks.","problem":"Onion maggots in cool, wet soil. Plant onion-family crops in a different spot each year.","varieties":["French Gray (gourmet, very hardy)","Ambition","Dutch Yellow"]},"asparagus":{"difficulty":2,"sun":"Full sun","spacing":"12 to 18 inches apart","depth":"In a trench 6 to 8 inches deep, covered gradually as the spears grow","plantText":"asparagus crowns","firstHarvest":"Light picking in year two; full harvests from year three","harvest":"Snap spears at soil level when they're 6 to 8 inches tall. Stop picking when new spears are pencil-thin, and let the ferns grow.","problem":"Asparagus beetles chew the spears and ferns. Hand-pick them in the morning.","varieties":["Jersey Knight","Millennium","Purple Passion"],"care":"Fill the trench in gradually as the shoots grow. Keep the bed weeded, and cut the ferns down only after they turn brown in fall."},"rhubarb":{"difficulty":1,"sun":"Full sun to part shade","spacing":"3 to 4 feet apart","depth":"Crown buds 1 to 2 inches below the surface","plantText":"rhubarb crowns","firstHarvest":"Light picking in year two; full harvests from year three","harvest":"Pull (don't cut) stalks when they're 10 to 15 inches long. Take no more than a third at once, and stop in early summer. Never eat the leaves.","problem":"Crown rot in soggy soil. In wet west-side gardens, plant on a slight mound or in a raised bed.","varieties":["Victoria","Canada Red","Crimson Red"],"care":"Mulch with compost each spring, and cut off flower stalks as soon as they appear."},"chives":{"difficulty":1,"sun":"Full sun to part shade","spacing":"8 to 12 inches apart","depth":"¼ inch deep","harvest":"Snip leaves an inch above the soil whenever you need them. The purple flowers are edible too.","problem":"Few pests. Clumps get crowded after a few years; dig and divide them in spring.","varieties":["Common chives","Garlic chives","Staro"]},"mint":{"difficulty":1,"sun":"Full sun to part shade","spacing":"One plant per pot, or 18 inches apart","depth":"Plant at the depth it grew in the nursery pot","plantText":"young mint plants","firstHarvest":"Pick lightly the first summer, then as much as you like","harvest":"Snip stems just above a pair of leaves. Regular cutting keeps plants bushy.","problem":"Mint spreads underground and takes over beds. Grow it in a container.","varieties":["Spearmint","Peppermint","Mojito mint"],"care":"Water regularly; mint likes moist soil. Cut it back hard in midsummer for a fresh flush of leaves."},"rosemary":{"difficulty":2,"sun":"Full sun","spacing":"24 to 36 inches apart","depth":"Plant at the depth it grew in the nursery pot","plantText":"young rosemary plants","firstHarvest":"Pick sprigs a few weeks after planting, once new growth appears","harvest":"Snip sprig tips as needed. Don't cut back into bare wood; it won't regrow.","problem":"Wet winter soil kills more rosemary than cold does. Plant in fast-draining soil or a raised bed.","varieties":["Arp (selected for cold hardiness)","Hill Hardy","Tuscan Blue"],"care":"Water until established, then only in dry spells. In cold eastern areas, grow it in a pot and move it to a cool, bright spot for winter.","frost":"Handles light frost; wet winter soil is the bigger risk"},"thyme":{"difficulty":1,"sun":"Full sun","spacing":"12 inches apart","depth":"Plant at the depth it grew in the nursery pot","plantText":"young thyme plants","firstHarvest":"Pick lightly the first year, freely after that","harvest":"Snip sprigs before the plant flowers for the best flavor. Trim lightly after flowering to keep it compact.","problem":"Root rot in heavy, wet soil. Give it gravelly soil or a raised spot.","varieties":["English thyme","French thyme","Lemon thyme"],"care":"Water only until established; thyme prefers dry soil. Replace plants every few years when they get woody."},"oregano":{"difficulty":1,"sun":"Full sun","spacing":"12 to 18 inches apart","depth":"Plant at the depth it grew in the nursery pot","plantText":"young oregano plants","firstHarvest":"Pick lightly the first year, freely after that","harvest":"Cut stems just before flowering, when flavor peaks. Dry bunches upside down in a shady, airy spot.","problem":"Few pests. Plants sprawl and get woody; cut them back by half in early summer.","varieties":["Greek oregano (strongest flavor)","Italian oregano","Golden oregano"],"care":"Water sparingly once established. Rich soil makes the flavor milder, so skip the fertilizer."},"sunflowers":{"difficulty":1,"sun":"Full sun","spacing":"6 inches (small types) to 24 inches (giants) apart","depth":"1 inch deep","firstHarvest":"Blooms about 60 to 90 days after sowing","harvest":"Cut flowers when the petals are just opening. For seeds, let heads dry on the plant until the back turns brown, and cover them from birds.","problem":"Birds and slugs eat seedlings. Cover the seedbed until plants are a few inches tall.","varieties":["Mammoth Grey Stripe (giant)","ProCut (for cutting)","Teddy Bear (dwarf)"]},"sweet-peas":{"difficulty":2,"sun":"Full sun","spacing":"4 to 6 inches apart along a trellis","depth":"1 inch deep (soak seeds overnight first)","firstHarvest":"Blooms in early summer","harvest":"Cut stems every couple of days; the more you pick, the more they bloom. Plants stop flowering once pods form.","problem":"Aphids and powdery mildew late in the season. Sow early so plants peak before summer heat.","varieties":["Cupani (very fragrant)","Spencer mix","Royal Family (more heat-tolerant)"]},"tulips":{"difficulty":1,"sun":"Full sun","spacing":"4 to 6 inches apart","depth":"6 to 8 inches deep, pointed end up","firstHarvest":"Blooms in April and May","harvest":"Cut when buds show color but are still closed. After blooming, let the leaves die back on their own to feed the bulb.","problem":"Squirrels, voles and deer eat tulips. Plant bulbs in wire cages, or choose daffodils where animals are a problem.","varieties":["Darwin hybrids (return best)","Apeldoorn","Queen of Night"],"frost":"Fully hardy; needs winter cold to bloom"},"daffodils":{"difficulty":1,"sun":"Full sun to part shade","spacing":"4 to 6 inches apart","depth":"6 inches deep, pointed end up","firstHarvest":"Blooms from late winter to spring, depending on variety","harvest":"Cut when buds are just opening. Their sap harms other flowers in a vase, so stand them alone for a few hours first. Let the leaves die back on their own.","problem":"Bulbs rot in soggy soil. Plant on a slope or in well-drained beds.","varieties":["Tête-à-Tête (early, small)","Dutch Master","Thalia (white)"],"frost":"Fully hardy; needs winter cold to bloom"}},"glossary":[["Last frost date","last-frost","The date after which freezing nights usually stop in spring. Rainline Garden uses the typical (median) date: in half of years the last frost comes later, so tender crops wait longer."],["First frost date","first-frost","The date the first fall freeze usually arrives. Warm-season crops die at the first frost; cool-season crops keep going."],["Frost-free season","frost-free-season","The number of days between the last spring frost and the first fall frost. It's your growing season for tomatoes, squash and other tender crops."],["Sow seeds (direct sow)","direct-sow","Planting seeds straight into the garden soil where they'll grow, instead of starting them in pots."],["Starts (transplants)","starts","Young plants grown in small pots, either by you indoors or bought at a nursery, then planted in the garden."],["Start seeds indoors","start-indoors","Sowing seeds in trays inside, under lights or in a sunny window, weeks before it's warm enough outside. It gives slow crops like tomatoes and peppers a head start."],["Hardening off","hardening-off","Getting indoor seedlings used to sun, wind and cool nights by setting them outside for a few hours a day, longer each day, for about a week before planting."],["Cool-season crop","cool-season","A crop that grows best in cool weather and handles light frost, like peas, lettuce, kale and carrots. Plant these in early spring and again for fall."],["Warm-season crop","warm-season","A crop that's killed by frost and needs warm soil, like tomatoes, beans, squash and basil. Plant these after the last frost once the soil warms."],["Soil temperature","soil-temperature","How warm the soil is a few inches down. In the Northwest it lags weeks behind the air, which is why warm crops wait. A soil thermometer costs about $10."],["Bolting","bolting","When a leafy crop like spinach or lettuce suddenly sends up a flower stalk, usually in heat or long days. The leaves turn bitter, so harvest before it happens."],["Thinning","thinning","Pulling out extra seedlings so the rest have room to grow. Carrots, beets and radishes need it."],["Succession planting","succession","Sowing a short row every two or three weeks instead of all at once, so you get a steady harvest."],["Row cover","row-cover","A light fabric laid over plants. It traps warmth, guards against light frost and keeps insects off."],["Wall-o-water and cloches","cloche","Covers that sit over a single plant to keep it warm. A wall-o-water is a ring of water-filled tubes that soaks up heat by day and releases it at night."],["Mulch","mulch","A layer of straw, leaves, compost or plastic on top of the soil. It holds moisture, smothers weeds and, if dark plastic, warms the soil."],["Days to harvest","days-to-harvest","Roughly how long from planting outdoors until the first harvest. Seed packets list it; it's longer in cool summers."],["Onion sets","onion-sets","Small dormant onion bulbs you plant instead of seeds. They're the easiest way to grow onions."],["Seed potatoes","seed-potatoes","Potatoes grown to be planted, certified free of disease. Grocery-store potatoes are often treated to stop sprouting."],["Curing","curing","Drying a harvest so it stores well: winter squash in a warm room, onions and garlic in a shady, airy spot."],["Cover crop","cover-crop","A crop like crimson clover or cereal rye sown in empty beds over winter to protect and feed the soil."],["Hardneck and softneck garlic","hardneck-softneck","Hardneck garlic has a stiff center stalk, bigger cloves and better cold tolerance. Softneck stores longer and can be braided."]],"beginner":["radishes","lettuce","beans","summer-squash","kale"],"beginnerWhy":{"radishes":"Ready in about four weeks, so you see results fast.","lettuce":"Grows in cool weather and a bit of shade, and you can pick it for weeks.","beans":"Big seeds that are easy to plant, and one sowing feeds you all summer.","summer-squash":"Two plants are plenty. It almost always produces.","kale":"Shrugs off Northwest cold and keeps going into winter."}};
